<?php
require_once __DIR__.'/includes/functions.php';
$exists=(int)$koneksi->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetch_row()[0]>0;$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){csrfCheck();$nama=trim($_POST['nama']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$kon=$_POST['konfirmasi']??'';try{if(!$nama||!$username||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('Lengkapi nama, username, dan email dengan benar.');if(strlen($pw)<10||$pw!==$kon)throw new Exception('Password minimal 10 karakter dan harus sama.');$hash=password_hash($pw,PASSWORD_DEFAULT);$role='admin';$s=$koneksi->prepare('INSERT INTO users(nama,username,email,password,role,status_akun) VALUES(?,?,?,?,?,\'aktif\')');$s->bind_param('sssss',$nama,$username,$email,$hash,$role);$s->execute();$exists=true;flash('Admin pertama berhasil dibuat. Silakan login.');redirect('login.php');}catch(Throwable $e){$err=$e->getMessage();}}
$pageTitle='Buat Admin Pertama';require __DIR__.'/includes/header.php';?><div class="auth-page" style="margin:-30px -34px -45px"><div class="auth-card"><img class="auth-logo" src="<?=e(url('assets/img/logo-sibara.png'))?>"><h1>Setup admin pertama</h1><p class="sub">Halaman ini otomatis terkunci setelah admin pertama dibuat.</p><?php if($exists):?><div class="alert">Admin sudah tersedia. Setup awal telah dinonaktifkan.</div><a class="btn" style="width:100%" href="<?=e(url('login.php'))?>">Ke halaman login</a><?php else:?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><?php foreach(['nama'=>'Nama lengkap','username'=>'Username','email'=>'Email'] as $n=>$l):?><div class="field"><label><?=$l?></label><input name="<?=$n?>" required></div><?php endforeach;?><div class="field"><label>Password (min. 10 karakter)</label><input type="password" name="password" minlength="10" required></div><div class="field"><label>Konfirmasi password</label><input type="password" name="konfirmasi" required></div><button class="btn" style="width:100%">Buat admin</button></form><?php endif;?></div></div><?php require __DIR__.'/includes/footer.php';?>
